 */

@font-face {
  font-family: "XB Tabriz";
  src: url("./XBTabriz-Regular.woff2") format("woff2");
  font-weight: 400;
  font-style: normal;
  font-display: swap;
}

@font-face {
  font-family: "XB Tabriz";
  src: url("./XBTabriz-Bold.woff2") format("woff2");
  font-weight: 700;
  font-style: normal;
  font-display: swap;
}

@font-face {
  font-family: "XB Tabriz";
  src: url("./XBTabriz-Italic.woff2") format("woff2");
  font-weight: 400;
  font-style: italic;
  font-display: swap;
}

@font-face {
  font-family: "XB Tabriz";
  src: url("./XBTabriz-BoldItalic.woff2") format("woff2");
  font-weight: 700;
  font-style: italic;
  font-display: swap;
}
